 1	// Write an *iterative* Dafny method Reverse with signature:
 2	//          method Reverse(a: array<char>) returns (b: array<char>)
 3	
 4	// which takes an input array of characters 'a' and outputs array 'b' consisting of
 5	// the elements of the input array in reverse order. The following conditions apply:
 6	//  - the input array cannot be empty
 7	//  - the input array is not modified
 8	//  - you must use iteration
 9	//  - not permitted is an *executable* (parallel) forall statement
10	//  - not permitted are any other predicates, functions or methods
11	
12	// For the purposes of this practice exercise, I'll include a test method.
13	
14	method Reverse(a: array<char>) returns (b: array<char>)
15	requires a.Length > 0
16	ensures a.Length == b.Length
17	ensures forall k :: 0 <= k < a.Length ==> b[k] == a[(a.Length-1) - k];
18	{
19	    b := new char[a.Length];
20	    assert b.Length == a.Length;
21	    var i:= 0;
22	
23	
24	    while(i < a.Length)
25	    invariant 0<=i<= (a.Length) + 1
26	    // invariant 0 < i <= a.Length-1 ==> b[i-1] == a[(a.Length-1) - i+1] // Not good enough
27	    invariant forall k :: 0 <= k < i ==> b[k] == a[(a.Length-1) - k]
28	    {
29	        b[i] := a[(a.Length-1) - i];
30	        i := i + 1;
31	    }
32	    
33	    // assert forall k :: 0 <= k < a.Length ==> a[k] == b[(a.Length-1) - k];
34	
35	
36	}
37	
38	
39	
40	method Main()
41	{
42	  var a := new char[8];
43	  a[0], a[1], a[2], a[3], a[4], a[5], a[6], a[7] := 'd', 'e', 's', 'r', 'e', 'v', 'e', 'r';
44	  var b := Reverse(a);
45	  assert b[..] == [ 'r', 'e', 'v', 'e', 'r', 's', 'e', 'd' ];
46	  print b[..];
47	
48	  a := new char[1];
49	  a[0] := '!';
50	  b := Reverse(a);
51	  assert b[..] == [ '!' ];
52	  print b[..], '\n';
53	}
54	
55	// Notice it compiles and the executable generates output (just to see the arrays printed in reverse).

